perl -Mstrict -Mwarnings -e '
my "'$seq_file="/workspace/run_trace/downloads/sequences_export_tabular.tsv";
my $table_file="/workspace/run_trace/downloads/feature_table_classic.tsv";
my $sample_file="/workspace/run_trace/sample_ids.txt";
my $out="/workspace/final_answer/asv_abundance.tsv";
open my $sf,"<",$sample_file or die $!;
my @samples=map { chomp; $_ } grep { /'"\\S/ } <"'$sf>;
close $sf;
my %wanted=map { $_=>1 } @samples;
my %id_to_seq;
open my $seqfh,"<",$seq_file or die $!;
while(<$seqfh>){ chomp; next unless length; my($id,$seq)=split /'"\\t/,"'$_,2; die "bad sequence row $.'"\\n\" unless defined "'$seq; $seq=uc($seq); die "non-DNA sequence for $id'"\\n\" unless "'$seq =~ /''^[ACGTN]+$/; $id_to_seq{$id}=$seq; }
close $seqfh;
open my $tfh,"<",$table_file or die $!;
my @header; my %col;
while(<$tfh>){ chomp; next if /''^# Constructed/; if(/''^#OTU ID'"\\t/){ @header=split /\\t/; "'$header[0]="feature_id"; for my $i (1..$#header){ $col{$header[$i]}=$i } last; } }
die "missing BIOM TSV header'"\\n\" unless @header;
for my "'$s (@samples){ die "missing sample column $s'"\\n\" unless exists "'$col{$s}; }
for my $s (@header[1..$#header]){ die "unexpected sample column $s'"\\n\" unless "'$wanted{$s}; }
open my $ofh,">",$out or die $!;
print $ofh join("'"\\t\", \"sequence\", @samples), \"\\n\";
my %seen_seq; my "'$rows=0;
while(<$tfh>){ chomp; next unless length; my @f=split /'"\\t/; my "'$id=$f[0]; die "missing sequence for feature $id'"\\n\" unless exists "'$id_to_seq{$id}; my $seq=$id_to_seq{$id}; die "duplicate ASV sequence $seq'"\\n\" if "'$seen_seq{$seq}++;
  my @counts; for my $s (@samples){ my $v=$f[$col{$s}]; die "missing count for $id $s'"\\n\" unless defined "'$v; die "invalid count $v for $id $s'"\\n\" unless "'$v =~ /''^'"\\d+(?:\\.0+)?"'$/; $v =~ s/'"\\.0+"'$//; push @counts, $v; }
  print $ofh join("'"\\t\", "'$seq, @counts), "'"\\n\"; "'$rows++;
}
close $tfh; close $ofh;
die "no ASV rows'"\\n\" unless "'$rows;
print "wrote $rows ASV rows to $out'"\\n\";
'"
